DG.put("zafarnaamah/1",{"n":1,"title":"ਜ਼ਫ਼ਰਨਾਮਹ ਸ੍ਰੀ ਮੁਖਵਾਕ ਪਾਤਿਸ਼ਾਹੀ ੧੦","title_roman":"Zafarnaamah sree mukhvaak paatishaahee 10","page":2537,"blocks":[{"type":"verse","number":[1],"number_text":"੧।","page":2537,"lines":[{"gurmukhi":"ਕਮਾਲੇ ਕਰਾਮਾਤ ਕਾਯਮ ਕਰੀਮ।","roman":"Kamaale karaamaat kaayam kareem |","meaning_en":"(He is) perfect in miracles, eternal, bountiful;","page":2537,"meaning_status":"draft","note":"Opening praise of God. ਕਮਾਲੇ ਕਰਾਮਾਤ: 'perfect in wonders'. ਕਾਯਮ: eternal. ਕਰੀਮ: bountiful."},{"gurmukhi":"ਰਜ਼ਾ ਬਖ਼ਸ਼ੋ ਰਾਜ਼ਿਕ ਰਿਹਾਕੋ ਰਹੀਮ। ੧।","roman":"Razaa bakhsho raazik rihaako raheem | 1 |","meaning_en":"giver of contentment, provider, deliverer, merciful.","page":2537,"meaning_status":"draft","note":"ਰਜ਼ਾ ਬਖ਼ਸ਼: giver of contentment (or of His will). ਰਿਹਾਕੋ: deliverer (from rihai, release)."}]},{"type":"verse","number":[2],"number_text":"੨।","page":2537,"lines":[{"gurmukhi":"ਅਮਾਂ ਬਖ਼ਸ਼ੋ ਬਖ਼ਸ਼ਿੰਦ ਓ ਦਸਤਗੀਰ।","roman":"Amaan bakhsho bakhshind o dasatgeer |","meaning_en":"Giver of protection, forgiver, holder of the hand (helper);","page":2537,"meaning_status":"draft","note":"ਦਸਤਗੀਰ: 'who takes the hand', helper."},{"gurmukhi":"ਰਜ਼ਾ ਬਖ਼ਸ਼ ਰੋਜ਼ੀ ਦਿਹੋ ਦਿਲ ਪਜ਼ੀਰ। ੨।","roman":"Razaa bakhash rozee diho dil pazeer | 2 |","meaning_en":"giver of contentment, giver of daily bread, winner of hearts.","page":2537,"meaning_status":"draft","note":"ਦਿਲ ਪਜ਼ੀਰ: 'pleasing to the heart'."}]},{"type":"verse","number":[3],"number_text":"੩।","page":2537,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਿ ਖ਼ੂਬੀ ਦਿਹੋ ਰਹ ਨਮੂੰ।","roman":"Shahinshaahi khoobee diho rah namoon |","meaning_en":"King of kings, giver of goodness, guide of the way;","page":2537,"meaning_status":"draft","note":"ਰਹ ਨਮੂੰ: guide (rahnuma)."},{"gurmukhi":"ਕਿ ਬੇਗੂੰਨ ਬੇਚੂੰਨ ਚੂੰ ਬੇਨਮੂੰ। ੩।","roman":"Ki begoonn bechoonn choon benmoon | 3 |","meaning_en":"without colour, without likeness, without equal.","page":2537,"meaning_status":"draft","note":"ਬੇਗੂੰਨ: without colour (or quality); ਬੇਚੂੰਨ: beyond comparison; ਬੇਨਮੂੰ: without example."}]},{"type":"verse","number":[4],"number_text":"੪।","page":2537,"lines":[{"gurmukhi":"ਨ ਸਾਜ਼ੋ ਨ ਬਾਜ਼ੋ ਨ ਫ਼ੌਜੋ ਨ ਫ਼ਰਸ਼।","roman":"Na saazo na baazo na faujo na farash |","meaning_en":"He has no equipment, no falcon, no army, no carpet (no royal trappings);","page":2537,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਬਖ਼ਸ਼ਿੰਦਏ ਐਸ਼ੁ ਅਰਸ਼। ੪।","roman":"Khudaavand bakhshindae aishu arash | 4 |","meaning_en":"yet He is the Lord, the giver of the joys of heaven.","page":2537,"meaning_status":"draft","note":"ਐਸ਼ੁ ਅਰਸ਼: 'the delights of heaven' (arsh: the highest heaven, God's throne)."}]},{"type":"verse","number":[5],"number_text":"੫।","page":2537,"lines":[{"gurmukhi":"ਜਹਾਂ ਪਾਕ ਜ਼ਬਰਸਤ ਜ਼ਾਹਿਰ ਜ਼ਹੂਰ।","roman":"Jahaan paak zabarsat zaahir zahoor |","meaning_en":"Pure beyond the world, mighty, His presence manifest;","page":2537,"meaning_status":"draft","note":"ਜਹਾਂ ਪਾਕ: read as 'pure above the world' or 'the pure one of the world'."},{"gurmukhi":"ਅਤਾ ਮੇ ਦਿਹਦ ਹਮ ਚੁ ਹਾਜ਼ਿਰ ਹਜ਼ੂਰ। ੫।","roman":"Ataa me dihad ham chu haazir hazoor | 5 |","meaning_en":"He gives gifts as though present before you.","page":2537,"meaning_status":"draft","note":"ਅਤਾ ਮੇ ਦਿਹਦ: 'gives gifts'. ਹਾਜ਼ਿਰ ਹਜ਼ੂਰ: present in person."}]},{"type":"verse","number":[6],"number_text":"੬।","page":2537,"lines":[{"gurmukhi":"ਅਤਾ ਬਖ਼ਸ਼ਓ ਪਾਕ ਪਰਵਰਦਿਗਾਰ।","roman":"Ataa bakhshao paak parvardigaar |","meaning_en":"The giver of gifts, the pure Sustainer;","page":2537,"meaning_status":"draft","note":"ਪਰਵਰਦਿਗਾਰ: Sustainer, Lord."},{"gurmukhi":"ਰਹੀਮ ਅਸਤੋ ਰੋਜ਼ੀ ਦਿਹੋ ਹਰ ਦਿਯਾਰ। ੬।","roman":"Raheem asto rozee diho har diyaar | 6 |","meaning_en":"He is merciful, giver of daily bread in every land.","page":2537,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":2537,"lines":[{"gurmukhi":"ਕਿ ਸਾਹਿਬ ਦਿਆਰ ਅਸਤੁ ਆਜ਼ਮ ਅਜ਼ੀਮ।","roman":"Ki saahib diaar astu aazam azeem |","meaning_en":"He is the Master of every region, the greatest of the great;","page":2537,"meaning_status":"draft","note":"ਆਜ਼ਮ ਅਜ਼ੀਮ: 'greatest, mighty'."},{"gurmukhi":"ਕਿ ਹੁਸਨੁਲ ਜਮਾਲ ਅਸਤੁ ਰਾਜ਼ਕ ਰਹੀਮ। ੭।","roman":"Ki husnul jamaal astu raazak raheem | 7 |","meaning_en":"of perfect beauty, the merciful Provider.","page":2537,"meaning_status":"draft","note":"ਹੁਸਨੁਲ ਜਮਾਲ: 'beauty of beauties'."}]},{"type":"verse","number":[8],"number_text":"੮।","page":2537,"lines":[{"gurmukhi":"ਕਿ ਸਾਹਿਬ ਸ਼ਊਰ ਅਸਤੁ ਆਜਿਜ਼ ਨਿਵਾਜ਼।","roman":"Ki saahib shaoor astu aajiz nivaaz |","meaning_en":"He is the master of wisdom, the cherisher of the humble;","page":2537,"meaning_status":"draft","note":"ਸ਼ਊਰ: discernment. ਆਜਿਜ਼ ਨਿਵਾਜ਼: 'favourer of the humble'."},{"gurmukhi":"ਗਰੀਬੁਲ ਪ੍ਰਸਤੋ ਗਨੀਮੁਲ ਗੁਦਾਜ਼। ੮।","roman":"Gareebul prasto ganeemul gudaaz | 8 |","meaning_en":"protector of the poor, destroyer of enemies.","page":2537,"meaning_status":"draft","note":"ਗਰੀਬੁਲ ਪ੍ਰਸਤ: 'cherisher of the poor'. ਗਨੀਮੁਲ ਗੁਦਾਜ਼: 'melter of enemies'."}]},{"type":"verse","number":[9],"number_text":"੯।","page":2537,"lines":[{"gurmukhi":"ਸ਼ਰੀਅਤ ਪ੍ਰਸਤੋ ਫ਼ਜ਼ੀਲਤ ਮਆਬ।","roman":"Shareeat prasto fazeelat ma'aab |","meaning_en":"Upholder of the law (shariat), the fount of excellence;","page":2537,"meaning_status":"draft","note":"Some read this and the next couplet as praise of God; others as describing how the Guru regards true faith. Uncertain who is meant."},{"gurmukhi":"ਹਕੀਕਤ ਸ਼ਨਾਸੋ ਨਬੀਉਲ ਕਿਤਾਬ। ੯।","roman":"Hakeekat shanaaso nabeeul kitaab | 9 |","meaning_en":"knower of truth, (the source of) the Prophet and the Book.","page":2537,"meaning_status":"draft","note":"ਨਬੀਉਲ ਕਿਤਾਬ: 'prophet of the Book'; uncertain in this context."}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2537,"lines":[{"gurmukhi":"ਕਿ ਦਾਨਿਸ਼ ਪਿਯੂਹਸਤੁ ਸਾਹਿਬ ਸ਼ਊਰ।","roman":"Ki daanish piyoohastu saahib shaoor |","meaning_en":"He is the seeker (source) of wisdom, the master of discernment;","page":2537,"meaning_status":"draft","note":"ਦਾਨਿਸ਼ ਪਿਯੂਹ: 'searcher of knowledge'."},{"gurmukhi":"ਹਕੀਕਤ ਸ਼ਨਾਸਸਤੁ ਜ਼ਾਹਰ ਜ਼ਹੂਰ। ੧੦।","roman":"Hakeekat shanaasastu zaahar zahoor | 10 |","meaning_en":"the knower of reality, manifest in His appearing.","page":2537,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":2537,"lines":[{"gurmukhi":"ਸ਼ਨਾਸਿੰਦਏ ਇਲਮਿ ਆਲਮ ਖ਼ੁਦਾਇ।","roman":"Shanaasindae ilmi aalam khudaai |","meaning_en":"The knower of the world's knowledge, God;","page":2537,"meaning_status":"draft"},{"gurmukhi":"ਕੁਸ਼ਾਇੰਦਏ ਕਾਰਿ ਆਲਮ ਕੁਸ਼ਾਇ। ੧੧।","roman":"Kushaaindae kaari aalam kushaai | 11 |","meaning_en":"the opener of the world's affairs, the opener (of all).","page":2537,"meaning_status":"draft","note":"ਕੁਸ਼ਾਇੰਦਏ: 'who opens / resolves'."}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":2537,"lines":[{"gurmukhi":"ਗੁਜ਼ਾਰਿੰਦਏ ਕਾਰਿ ਆਲਮ ਕਬੀਰ।","roman":"Guzaarindae kaari aalam kabeer |","meaning_en":"He carries out the affairs of the world, the Great;","page":2537,"meaning_status":"draft","note":"ਕਬੀਰ: great (Arabic)."},{"gurmukhi":"ਸ਼ਨਾਸਿੰਦਏ ਇਲਮਿ ਆਲਮ ਅਮੀਰ। ੧੨।","roman":"Shanaasindae ilmi aalam ameer | 12 |","meaning_en":"the knower of the world's knowledge, the Commander.","page":2537,"meaning_status":"draft","note":"ਅਮੀਰ: commander, ruler."}]},{"type":"heading","kind":"chhand","name":"ਦਾਸਤਾਨ","gurmukhi":"ਦਾਸਤਾਨ","roman":"Daastaan","meaning_en":"The story (Dastan).","page":2539,"meaning_status":"draft","note":"Here the letter turns from praise to the account of events."},{"type":"verse","number":[13],"number_text":"੧੩।","page":2539,"lines":[{"gurmukhi":"ਮਰਾ ਏਤਬਾਰੇ ਬਰੀਂ ਕਸਮ ਨੇਸਤ।","roman":"Maraa etbaare bareen kasam nesat |","meaning_en":"I have no faith at all in your oath;","page":2539,"meaning_status":"draft","note":"Addressed to Aurangzeb, whose officers swore on the Quran that the Guru could leave Anandpur safely, then attacked."},{"gurmukhi":"ਕਿ ਏਜ਼ਦ ਗਵਾਹਸਤੁ ਯਜ਼ਦਾਂ ਯਕੇਸਤ। ੧੩।","roman":"Ki ezad gavaahastu yazdaan yakesat | 13 |","meaning_en":"God is witness, and God is One.","page":2539,"meaning_status":"draft","note":"ਏਜ਼ਦ / ਯਜ਼ਦਾਂ: God (Persian)."}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2539,"lines":[{"gurmukhi":"ਨ ਕਤਰਹ ਮਰਾ ਏਤਬਾਰੇ ਬਰੋਸਤ।","roman":"Na katrah maraa etbaare barosat |","meaning_en":"Not a drop of trust have I in him,","page":2539,"meaning_status":"draft","note":"ਬਰੋਸਤ: 'in him'; read as Aurangzeb, or his officers."},{"gurmukhi":"ਕਿ ਬਖ਼ਸ਼ੀ ਵ ਦੀਵਾਂ ਹਮਹ ਕਿਜ਼ਬਗੋਸ਼ਤ। ੧੪।","roman":"Ki bakhshee va deevaan hamah kizabgoshat | 14 |","meaning_en":"for your paymaster and ministers are all liars.","page":2539,"meaning_status":"draft","note":"ਬਖ਼ਸ਼ੀ: paymaster (an imperial officer). ਦੀਵਾਂ: minister. ਕਿਜ਼ਬਗੋ: liar."}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":2539,"lines":[{"gurmukhi":"ਕਸੇ ਕਉਲਿ ਕੁਰਆਂ ਕੁਨਦ ਏਤਬਾਰ।","roman":"Kase kauli kura'aan kunad etbaar |","meaning_en":"Whoever trusts your oath on the Quran,","page":2539,"meaning_status":"draft"},{"gurmukhi":"ਹਮਾ ਰੋਜ਼ਿ ਆਖ਼ਿਰ ਸ਼ਵਦ ਮਰਦ ਖ਼੍ਵਾਰ। ੧੫।","roman":"Hamaa rozi aakhir shavad marad khvaar | 15 |","meaning_en":"that man will in the end be ruined.","page":2539,"meaning_status":"draft","note":"ਹਮਾ ਰੋਜ਼ਿ ਆਖ਼ਿਰ: 'in the end'. ਖ਼੍ਵਾਰ: disgraced, ruined."}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":2539,"lines":[{"gurmukhi":"ਹੁਮਾ ਰਾ ਕਸੇ ਸਾਯਹ ਆਯਦ ਬਜ਼ੇਰ।","roman":"Humaa raa kase saayah aayad bazer |","meaning_en":"Whoever comes under the shadow of the Huma bird,","page":2539,"meaning_status":"draft","note":"Huma: a legendary bird whose shadow brings kingship and protection."},{"gurmukhi":"ਬਰੋ ਦਸਤ ਦਾਰਦ ਨ ਜ਼ਾਗੋ ਦਲੇਰ। ੧੬।","roman":"Baro dasat daarad na zaago daler | 16 |","meaning_en":"no bold crow can lay a hand on him.","page":2539,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":2539,"lines":[{"gurmukhi":"ਕਸੇ ਪੁਸ਼ਤ ਉਫ਼ਤਦ ਪਸੇ ਸ਼ੇਰਿ ਨਰ।","roman":"Kase pushat uftad pase sheri nar |","meaning_en":"Whoever takes shelter behind a tiger,","page":2539,"meaning_status":"draft"},{"gurmukhi":"ਨਗੀਰਦ ਬੁਜ਼ੋ ਮੇਸ਼ੋ ਆਹੂ ਗੁਜ਼ਰ। ੧੭।","roman":"Nageerad buzo mesho aahoo guzar | 17 |","meaning_en":"no goat, sheep or deer can catch him.","page":2539,"meaning_status":"draft","note":"Read as: the one under God's protection cannot be harmed by lesser beings."}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":2539,"lines":[{"gurmukhi":"ਕਸਮ ਮੁਸਹਫ਼ੇ ਖ਼ੁਫ਼ੀਯਹ ਗਰ ਈਂ ਖ਼ੁਰਮ।","roman":"Kasam musahfe khufeeyah gar een khuram |","meaning_en":"If I had (not) secretly sworn on the Quran (?), ...","page":2539,"meaning_status":"draft","note":"This couplet is obscure; read by some as: 'Had I not trusted the secret oath on the Quran, I would not have let my army be crushed under (enemy) hooves.' Uncertain."},{"gurmukhi":"ਨ ਫ਼ੌਜੇ ਅਜ਼ੀਂ ਜ਼ੇਰ ਸੁਮ ਅਫ਼ਕੁਨਮ। ੧੮।","roman":"Na fauje azeen zer sum afkunam | 18 |","meaning_en":"I would not have brought my army under (the enemy's) hooves.","page":2539,"meaning_status":"draft","note":"ਜ਼ੇਰ ਸੁਮ: 'under the hooves'. See note on the previous line."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":2539,"lines":[{"gurmukhi":"ਗੁਰਸਨਹ ਚਿ ਕਾਰੇ ਕੁਨਦ ਚਿਹਲ ਨਰ।","roman":"Gurasnah chi kaare kunad chihal nar |","meaning_en":"What can forty men do when hungry,","page":2539,"meaning_status":"draft","note":"Refers to the battle of Chamkaur, where about forty Sikhs faced a huge army. ਗੁਰਸਨਹ: hungry."},{"gurmukhi":"ਕਿ ਦਹ ਲਖ ਬਰਆਯਦ ਬਰੋ ਬੇਖ਼ਬਰ। ੧੯।","roman":"Ki dah lakh bara'aayad baro bekhbar | 19 |","meaning_en":"when ten lakh (a million) men fall upon them unawares?","page":2539,"meaning_status":"draft"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2539,"lines":[{"gurmukhi":"ਕਿ ਪੈਮਾ ਸ਼ਿਕਨ ਬੇਦਰੰਗ ਅਮਾਦੰਦ।","roman":"Ki paimaa shikan bedrang amaadand |","meaning_en":"The breakers of the oath came at once,","page":2539,"meaning_status":"draft","note":"ਪੈਮਾ ਸ਼ਿਕਨ: oath-breakers. ਬੇਦਰੰਗ: without delay."},{"gurmukhi":"ਮਿਯਾਂ ਤੇਗ ਤੀਰੋ ਤੁਫ਼ੰਗ ਆਮਦੰਦ। ੨੦।","roman":"Miyaan teg teero tufang aamdand | 20 |","meaning_en":"with swords, arrows and guns.","page":2539,"meaning_status":"draft","note":"ਮਿਯਾਂ: read as 'in the midst / drawn'; uncertain."}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":2539,"lines":[{"gurmukhi":"ਬ ਲਾਚਾਰਗੀ ਦਰ ਮਿਯਾਂ ਆਮਦਮ।","roman":"Ba laachaargee dar miyaan aamdam |","meaning_en":"Out of necessity I came into the fight;","page":2539,"meaning_status":"draft"},{"gurmukhi":"ਬ ਤਦਬੀਰਿ ਤੀਰੋ ਤੁਫ਼ੰਗ ਆਮਦਮ। ੨੧।","roman":"Ba tadbeeri teero tufang aamdam | 21 |","meaning_en":"with the means of arrows and guns I came.","page":2539,"meaning_status":"draft"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2539,"lines":[{"gurmukhi":"ਚੁ ਕਾਰ ਅਜ਼ ਹਮਹ ਹੀਲਤੇ ਦਰ ਗੁਜ਼ਸ਼ਤ।","roman":"Chu kaar az hamah heelte dar guzshat |","meaning_en":"When all other means have failed,","page":2539,"meaning_status":"draft","note":"One of the best-known couplets of Zafarnama."},{"gurmukhi":"ਹਲਾਲ ਅਸਤੁ ਬੁਰਦਨ ਬ ਸ਼ਮਸ਼ੇਰ ਦਸਤ। ੨੨।","roman":"Halaal astu burdan ba shamsher dasat | 22 |","meaning_en":"it is right to take the sword in hand.","page":2539,"meaning_status":"draft","note":"ਹਲਾਲ: lawful, right."}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2539,"lines":[{"gurmukhi":"ਚਿ ਕਸਮੇ ਕੁਰਾਂ ਮਨ ਕੁਨਮ ਏਤਬਾਰ।","roman":"Chi kasme kuraan man kunam etbaar |","meaning_en":"Why should I trust the oath on the Quran?","page":2539,"meaning_status":"draft"},{"gurmukhi":"ਵਗਰਨਹ ਤੁ ਗੋਈ ਮਨ ਈਂ ਰਹ ਚਿ ਕਾਰ। ੨੩।","roman":"Vagarnah tu goee man een rah chi kaar | 23 |","meaning_en":"Otherwise, you say, what business had I on this path?","page":2539,"meaning_status":"draft","note":"Read as: 'had I not trusted it, I would not have taken this path'; uncertain."}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2539,"lines":[{"gurmukhi":"ਨ ਦਾਨਮ ਕਿ ਈਂ ਮਰਦ ਰੋਬਾਹ ਪੇਚ।","roman":"Na daanam ki een marad robaah pech |","meaning_en":"I did not know this man was cunning as a fox;","page":2539,"meaning_status":"draft","note":"ਰੋਬਾਹ ਪੇਚ: 'fox-like twists'."},{"gurmukhi":"ਵਗਰ ਹਰਗਿਜ਼ੀਂ ਰਹ ਨਯਾਰਦ ਬਹੇਚ। ੨੪।","roman":"Vagar hargizeen rah nayaarad bahech | 24 |","meaning_en":"otherwise I would never have come this way at all.","page":2539,"meaning_status":"draft"}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":2539,"lines":[{"gurmukhi":"ਹਰ ਆਂ ਕਸ ਕਿ ਕਉਲੇ ਕੁਰਾਂ ਆਯਦਸ਼।","roman":"Har aan kas ki kaule kuraan aaydash |","meaning_en":"Whoever comes (to me) on the word of the Quran,","page":2539,"meaning_status":"draft","note":"Read as: one who comes under an oath on the Quran should not be bound or killed."},{"gurmukhi":"ਨਜ਼ੋ ਬਸਤਨੋ ਕੁਸ਼ਤਨੀ ਬਾਯਦਸ਼। ੨੫।","roman":"Nazo basatno kushatnee baaydash | 25 |","meaning_en":"it is not right to bind him or to kill him.","page":2539,"meaning_status":"draft","note":"ਨਜ਼ੋ ਬਸਤਨੋ ਕੁਸ਼ਤਨੀ: 'not (fit) to bind or kill'."}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2539,"lines":[{"gurmukhi":"ਬਰੰਗੇ ਮਗਸ ਸ੍ਯਾਹਪੋਸ਼ ਆਮਦੰਦ।","roman":"Barange magas syaahposh aamdand |","meaning_en":"They came dressed in black, like flies,","page":2539,"meaning_status":"draft"},{"gurmukhi":"ਬ ਯਕ ਬਾਰਗੀ ਦਰ ਖ਼ਰੋਸ਼ ਆਮਦੰਦ। ੨੬।","roman":"Ba yak baargee dar kharosh aamdand | 26 |","meaning_en":"and all at once they came on shouting.","page":2539,"meaning_status":"draft","note":"ਖ਼ਰੋਸ਼: uproar."}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2541,"lines":[{"gurmukhi":"ਹਰ ਆਂ ਕਸ ਜ਼ਿ ਦੀਵਾਰ ਆਮਦ ਬਿਰੂੰ।","roman":"Har aan kas zi deevaar aamad biroon |","meaning_en":"Whoever came out from behind the wall,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਬਖ਼ੁਰਦਨ ਯਕੇ ਤੀਰ ਸ਼ੁਦ ਗਰਕਿ ਖ਼ੂੰ। ੨੭।","roman":"Bakhurdan yake teer shud garki khoon | 27 |","meaning_en":"on taking one arrow fell drowned in blood.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":2541,"lines":[{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਨਯਾਮਦ ਕਸੇ ਜ਼ਾਂ ਦੀਵਾਰ।","roman":"Ki beroon nayaamad kase zaan deevaar |","meaning_en":"Those who did not come out from behind that wall","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਨ ਖ਼ੁਰਦੰਦ ਤੀਰੋ ਨ ਗਸ਼ਤੰਦ ਖ਼੍ਵਾਰ। ੨੮।","roman":"Na khurdand teero na gashtand khvaar | 28 |","meaning_en":"were not struck by arrows and were not ruined.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2541,"lines":[{"gurmukhi":"ਚੁ ਦੀਦਮ ਕਿ ਨਾਹਰ ਬਿਯਾਮਦ ਬ ਜੰਗ।","roman":"Chu deedam ki naahar biyaamad ba jang |","meaning_en":"When I saw that Nahar (Khan) came into the battle,","page":2541,"meaning_status":"draft","note":"Nahar Khan: an officer of the imperial army."},{"gurmukhi":"ਚਸ਼ੀਦਹ ਯਕੇ ਤੀਰਿ ਮਨ ਬੇਦਰੰਗ। ੨੯।","roman":"Chasheedah yake teeri man bedrang | 29 |","meaning_en":"he tasted one of my arrows at once.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2541,"lines":[{"gurmukhi":"ਹਮਾਖ਼ਿਰ ਗੁਰੇਜ਼ਦ ਬਜਾਏ ਮਸਾਫ਼।","roman":"Hamaakhir gurezad bajaae masaaf |","meaning_en":"In the end many fled from the battlefield,","page":2541,"meaning_status":"draft","note":"ਮਸਾਫ਼: battlefield."},{"gurmukhi":"ਬਸੇ ਖ਼ਾਨਹ ਖ਼ੁਰਦੰਦ ਬੇਰੂੰ ਗੁਜ਼ਾਫ਼। ੩੦।","roman":"Base khaanah khurdand beroon guzaaf | 30 |","meaning_en":"many who had boasted (earlier) ... left the field.","page":2541,"meaning_status":"draft","note":"ਬਸੇ ਖ਼ਾਨਹ ਖ਼ੁਰਦੰਦ ਬੇਰੂੰ ਗੁਜ਼ਾਫ਼ is obscure; read as 'many Khans who had boasted ate (their words) and went out'. Uncertain."}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2541,"lines":[{"gurmukhi":"ਕਿ ਅਫ਼ਗਨੇ ਦੀਗਰ ਬਿਯਾਮਦ ਬਜੰਗ।","roman":"Ki afagne deegar biyaamad bajang |","meaning_en":"Then another Afghan came into the battle,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸੈਲੇ ਰਵਾਂ ਹਮ ਚੁ ਤੀਰੋ ਤੁਫ਼ੰਗ। ੩੧।","roman":"Chu saile ravaan ham chu teero tufang | 31 |","meaning_en":"like a rushing flood, like an arrow or a bullet.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2541,"lines":[{"gurmukhi":"ਬਸੇ ਹਮਲਹ ਕਰਦੰਦ ਬ ਮਰਦਾਨਗੀ।","roman":"Base hamlah kardand ba mardaangee |","meaning_en":"He made many attacks with bravery,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਅਜ਼ ਹੋਸ਼ਗੀ ਹਮ ਜ਼ਿ ਦੇਗਾਨਗੀ। ੩੨।","roman":"Ham az hoshgee ham zi degaangee | 32 |","meaning_en":"some with sense and some with madness.","page":2541,"meaning_status":"draft","note":"ਦੇਗਾਨਗੀ: madness (divanagi)."}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2541,"lines":[{"gurmukhi":"ਬਸੇ ਹਮਲਹ ਕਰਦਹ ਬਸੇ ਜ਼ਖ਼ਮ ਖ਼ੁਰਦ।","roman":"Base hamlah kardah base zakham khurad |","meaning_en":"He made many attacks and received many wounds;","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਦੁ ਕਸ ਰਾ ਬਜ਼ਾਂ ਕੁਸ਼ਤੋ ਹਮ ਜਾਂ ਸਪੁਰਦ। ੩੩।","roman":"Du kas raa bazaan kushto ham jaan sapurad | 33 |","meaning_en":"he killed two men and gave up his own life.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2541,"lines":[{"gurmukhi":"ਕਿ ਆਂ ਖ਼੍ਵਾਜਹ ਮਰਦੂਦ ਸਾਯਹ ਦੀਵਾਰ।","roman":"Ki aan khvaajah mardood saayah deevaar |","meaning_en":"That accursed Khwaja (stayed) in the shadow of the wall,","page":2541,"meaning_status":"draft","note":"Khwaja: Khwaja Mardud, a commander who hid behind a wall."},{"gurmukhi":"ਨਯਾਮਦ ਬ ਮੈਦਾਂ ਬ ਮਰਦਾਨਹ ਵਾਰ। ੩੪।","roman":"Nayaamad ba maidaan ba mardaanah vaar | 34 |","meaning_en":"and did not come into the field like a man.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2541,"lines":[{"gurmukhi":"ਦਰੇਗਾ ਅਗਰ ਰੂਇ ਓ ਦੀਦਮੇ।","roman":"Daregaa agar rooi o deedme |","meaning_en":"Alas! If I had seen his face,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਬ ਯਕ ਤੀਰ ਲਾਚਾਰ ਬਖ਼ਸ਼ੀਦਮੇ। ੩੫।","roman":"Ba yak teer laachaar bakhsheedme | 35 |","meaning_en":"I would have given him one arrow, without fail.","page":2541,"meaning_status":"draft","note":"ਲਾਚਾਰ: 'of necessity, certainly'."}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":2541,"lines":[{"gurmukhi":"ਹਮਾਖ਼ਿਰ ਬਸੇ ਜ਼ਖ਼ਮਿ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Hamaakhir base zakhmi teero tufang |","meaning_en":"In the end, many (were struck) by wounds of arrows and guns;","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਦੋ ਸੂਏ ਬਸੇ ਕੁਸ਼ਤਹ ਸ਼ੁਦ ਬੇਦਰੰਗ। ੩੬।","roman":"Do sooe base kushtah shud bedrang | 36 |","meaning_en":"on both sides many were killed at once.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":2541,"lines":[{"gurmukhi":"ਬਸੇ ਬਾਰ ਬਾਰੀਦ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Base baar baareed teero tufang |","meaning_en":"Arrows and bullets rained down many times,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿਮੀ ਗਸ਼ਤ ਹਮ ਚੂੰ ਗੁਲੇ ਲਾਲਹ ਰੰਗ। ੩੭।","roman":"Zimee gashat ham choon gule laalah rang | 37 |","meaning_en":"and the earth turned red like the tulip.","page":2541,"meaning_status":"draft","note":"ਗੁਲੇ ਲਾਲਹ: the tulip (or red poppy)."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2541,"lines":[{"gurmukhi":"ਸਰੋਪਾਇ ਅੰਬੋਹ ਚੰਦਾਂ ਸ਼ੁਦਹ।","roman":"Saropaai anboh chandaan shudah |","meaning_en":"Heaps of heads and feet were piled up,","page":2541,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮੈਦਾਂ ਪੁਰ ਅਜ਼ ਗੂਓ ਚੌਗਾਂ ਸ਼ੁਦਹ। ੩੮।","roman":"Ki maidaan pur az goo'o chaugaan shudah | 38 |","meaning_en":"so that the field was full of balls and sticks (as in polo).","page":2541,"meaning_status":"draft","note":"ਗੂਓ ਚੌਗਾਂ: the ball and stick of polo; heads and limbs compared to them."}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2541,"lines":[{"gurmukhi":"ਤਰੰਕਾਰਿ ਤੀਰੋ ਤਰੰਗਿ ਕਮਾਂ।","roman":"Tarankaari teero tarangi kamaan |","meaning_en":"The twang of arrows and the stretch of bows","page":2541,"meaning_status":"draft","note":"ਤਰੰਕਾਰ: the twanging sound."},{"gurmukhi":"ਬਰਾਮਦ ਯਕੇ ਹਾ ਓ ਹੂ ਅਜ਼ ਜਹਾਂ। ੩੯।","roman":"Baraamad yake haa o hoo az jahaan | 39 |","meaning_en":"raised a hue and cry from the world.","page":2541,"meaning_status":"draft","note":"ਹਾ ਓ ਹੂ: clamour."}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2541,"lines":[{"gurmukhi":"ਦਿਗਰ ਸ਼ੋਰਸ਼ਿ ਕੈਬਰਿ ਕੀਨਹ ਕੋਸ਼।","roman":"Digar shorshi kaibri keenah kosh |","meaning_en":"Then the clamour of the vengeful spears,","page":2541,"meaning_status":"draft","note":"ਕੈਬਰ: a kind of spear or arrow. ਕੀਨਹ ਕੋਸ਼: 'bent on vengeance'."},{"gurmukhi":"ਜ਼ਿ ਮਰਦਾਨਿ ਮਰਦਾਂ ਬਿਰੂੰ ਰਫ਼ਤ ਹੋਸ਼। ੪੦।","roman":"Zi mardaani mardaan biroon rafat hosh | 40 |","meaning_en":"made even the bravest of men lose their senses.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2541,"lines":[{"gurmukhi":"ਹਮ ਆਖ਼ਿਰ ਚਿ ਮਰਦੀ ਕੁਨਦ ਕਾਰਜ਼ਾਰ।","roman":"Ham aakhir chi mardee kunad kaarzaar |","meaning_en":"In the end, what manliness can be shown in the battle,","page":2541,"meaning_status":"draft","note":"ਕਾਰਜ਼ਾਰ: battle."},{"gurmukhi":"ਕਿ ਬਰ ਚਿਹਲ ਤਨ ਆਯਦਸ਼ ਬੇਸ਼ੁਮਾਰ। ੪੧।","roman":"Ki bar chihal tan aaydash beshumaar | 41 |","meaning_en":"when countless men fall upon forty?","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":2541,"lines":[{"gurmukhi":"ਚਰਾਗਿ ਜਹਾਂ ਚੂੰ ਸ਼ੁਦਹ ਬੁਰਕਹ ਪੋਸ਼।","roman":"Charaagi jahaan choon shudah burkah posh |","meaning_en":"When the lamp of the world (the sun) put on its veil,","page":2541,"meaning_status":"draft","note":"That is, when the sun set."},{"gurmukhi":"ਸ਼ਹੇ ਸ਼ਬ ਬਰਾਮਦ ਹਮਹ ਜਲਵਹ ਜੋਸ਼। ੪੨।","roman":"Shahe shab baraamad hamah jalvah josh | 42 |","meaning_en":"the king of night (the moon) came out in all its splendour.","page":2541,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":2543,"lines":[{"gurmukhi":"ਹਰ ਆਂ ਕਸ ਬਕਉਲੇ ਕੁਰਾਂ ਆਯਦਸ਼।","roman":"Har aan kas bakaule kuraan aaydash |","meaning_en":"Whoever comes trusting the word of the Quran,","page":2543,"meaning_status":"draft","note":"Read as: whoever trusts in God's word, God becomes his guide (the Guru's escape from Chamkaur)."},{"gurmukhi":"ਕਿ ਯਜ਼ਦਾਂ ਬਰੋ ਰਹਿਨੁਮਾ ਆਯਦਸ਼। ੪੩।","roman":"Ki yazdaan baro rahinumaa aaydash | 43 |","meaning_en":"God becomes his guide.","page":2543,"meaning_status":"draft","note":"ਰਹਿਨੁਮਾ: guide."}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2543,"lines":[{"gurmukhi":"ਨਿ ਪੇਚੀਦਹ ਮੂਏ ਨ ਰੰਜੀਦਹ ਤਨ।","roman":"Ni pecheedah mooe na ranjeedah tan |","meaning_en":"Not a hair was twisted, not the body hurt:","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਬੇਰੂੰ ਖ਼ੁਦ ਆਵੁਰਦ ਦੁਸ਼ਮਨ ਸ਼ਿਕਨ। ੪੪।","roman":"Ki beroon khud aavurad dushman shikan | 44 |","meaning_en":"He, the breaker of enemies, Himself brought me out.","page":2543,"flags":[{"code":"ੁੁ","reason":"same sign typed twice; written once (prints as one)"}],"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":2543,"lines":[{"gurmukhi":"ਨ ਦਾਨਮ ਕਿ ਈਂ ਮਰਦਿ ਪੈਮਾਂ ਸ਼ਿਕਨ।","roman":"Na daanam ki een mardi paimaan shikan |","meaning_en":"I did not know that this man was a breaker of oaths,","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਦੌਲਤ ਪਰਸਤ ਓ ਈਮਾਂ ਫ਼ਿਕਨ। ੪੫।","roman":"Ki daulat parsat o eemaan fikan | 45 |","meaning_en":"a worshipper of wealth and a thrower-away of faith.","page":2543,"meaning_status":"draft","note":"ਈਮਾਂ ਫ਼ਿਕਨ: 'one who casts off faith'."}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":2543,"lines":[{"gurmukhi":"ਨ ਈਮਾਂ ਪ੍ਰਸਤੀ ਨ ਔਜ਼ਾਇ ਦੀਂ।","roman":"Na eemaan prastee na auzaai deen |","meaning_en":"You have no keeping of faith, no (true) ways of religion;","page":2543,"meaning_status":"draft","note":"ਔਜ਼ਾਇ ਦੀਂ: 'the practices of the faith'."},{"gurmukhi":"ਨ ਸਾਹਿਬ ਸ਼ਨਾਸੀ ਨ ਮਹਮਦ ਯਕੀਂ। ੪੬।","roman":"Na saahib shanaasee na mahmad yakeen | 46 |","meaning_en":"no recognition of the Lord, no belief in Muhammad.","page":2543,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2543,"lines":[{"gurmukhi":"ਹਰ ਆਂ ਕਸ ਕਿ ਈਮਾਂ ਪ੍ਰਸਤੀ ਕੁਨਦ।","roman":"Har aan kas ki eemaan prastee kunad |","meaning_en":"Whoever keeps faith","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਨ ਪੈਮਾਂ ਖ਼ੁਦਸ਼ ਪੇਸ਼ੋ ਪਸਤੀ ਕੁਨਦ। ੪੭।","roman":"Na paimaan khudash pesho pastee kunad | 47 |","meaning_en":"does not go back and forth on his own oath.","page":2543,"meaning_status":"draft","note":"ਪੇਸ਼ੋ ਪਸਤੀ: 'forward and backward', i.e. waver. Uncertain."}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":2543,"lines":[{"gurmukhi":"ਕਿ ਈਂ ਮਰਦ ਰਾ ਜ਼ੱਰਹ ਏਤਬਾਰ ਨੇਸਤ।","roman":"Ki een marad raa zarrah etbaar nesat |","meaning_en":"This man deserves not a particle of trust,","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਕਸਮੇ ਕੁਰਾਨਸਤੁ ਯਜ਼ਦਾਂ ਯਕੇਸਤ। ੪੮।","roman":"Ki kasme kuraanastu yazdaan yakesat | 48 |","meaning_en":"though his oath is on the Quran and God is One.","page":2543,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":2543,"lines":[{"gurmukhi":"ਚੁ ਕਸਮੇ ਕੁਰਾਂ ਸਦ ਕੁਨਦ ਇਖ਼ਤਿਯਾਰ।","roman":"Chu kasme kuraan sad kunad ikhtiyaar |","meaning_en":"Even if he took a hundred oaths on the Quran,","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਮਰਾ ਕਤਰਹ ਨਾਯਦ ਅਜ਼ੋ ਏਤਬਾਰ। ੪੯।","roman":"Maraa katrah naayad azo etbaar | 49 |","meaning_en":"I would not trust him a drop.","page":2543,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2543,"lines":[{"gurmukhi":"ਅਗਰਚਿ ਤੁਰਾ ਏਤਬਾਰ ਆਮਦੇ।","roman":"Agarchi turaa etbaar aamde |","meaning_en":"If you had any trust (in your word),","page":2543,"meaning_status":"draft","note":"Addressed to Aurangzeb."},{"gurmukhi":"ਕਮਰ ਬਸਤ ਏ ਪੇਸ਼ਵਾ ਆਮਦੇ। ੫੦।","roman":"Kamar basat e peshvaa aamde | 50 |","meaning_en":"you would have girded your loins and come forward (yourself).","page":2543,"meaning_status":"draft","note":"ਪੇਸ਼ਵਾ: forward, in front."}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2543,"lines":[{"gurmukhi":"ਕਿ ਫ਼ਰਜ਼ਸਤੁ ਬਰ ਸਰ ਤੁਰਾ ਈਂ ਸੁਖ਼ਨ।","roman":"Ki farzastu bar sar turaa een sukhan |","meaning_en":"It is your duty (to keep) this word,","page":2543,"meaning_status":"draft","note":"ਫ਼ਰਜ਼: duty. ਬਰ ਸਰ: 'on your head'."},{"gurmukhi":"ਕਿ ਕੌਲੇ ਖ਼ੁਦਾ ਅਸਤੁ ਕਸਮਸਤੁ ਮਨ। ੫੧।","roman":"Ki kaule khudaa astu kasmastu man | 51 |","meaning_en":"for it was God's word and your oath to me.","page":2543,"meaning_status":"draft","note":"Read as: 'what was sworn on God's word is an oath to me'; uncertain."}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2543,"lines":[{"gurmukhi":"ਅਗਰ ਹਜ਼ਰਤੇ ਖ਼ੁਦ ਸਿਤਾਦਹ ਸ਼ਵਦ।","roman":"Agar hazarte khud sitaadah shavad |","meaning_en":"If His Majesty himself were to stand (here),","page":2543,"meaning_status":"draft","note":"ਹਜ਼ਰਤੇ: 'His Majesty' (Aurangzeb). ਸਿਤਾਦਹ: standing."},{"gurmukhi":"ਬ ਜਾਨੋ ਦਿਲੇ ਕਾਰ ਵਾਜ਼ਿਹ ਸ਼ਵਦ। ੫੨।","roman":"Ba jaano dile kaar vaazih shavad | 52 |","meaning_en":"the matter would become clear to his life and heart.","page":2543,"meaning_status":"draft","note":"ਵਾਜ਼ਿਹ: clear."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":2543,"lines":[{"gurmukhi":"ਸ਼ੁਮਾ ਰਾ ਫ਼ਰਜ਼ਸਤੁ ਕਾਰੇ ਕੁਨੀਂ।","roman":"Shumaa raa farzastu kaare kuneen |","meaning_en":"It is your duty to do this work:","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਬਮੂਜਬ ਨਵਿਸ਼ਤਹ ਸ਼ੁਮਾਰੇ ਕੁਨੀਂ। ੫੩।","roman":"Bamoojab navishtah shumaare kuneen | 53 |","meaning_en":"act according to what was written (in your letter).","page":2543,"meaning_status":"draft","note":"ਬਮੂਜਬ ਨਵਿਸ਼ਤਹ: 'according to what is written'."}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":2543,"lines":[{"gurmukhi":"ਨਵਿਸ਼ਤਹ ਰਸੀਦੋ ਬਗੁਫ਼ਤਹ ਜ਼ੁਬਾਂ।","roman":"Navishtah raseedo baguftah zubaan |","meaning_en":"The letter arrived, and the spoken word (came too):","page":2543,"meaning_status":"draft","note":"Refers to the emperor's letter and message received by the Guru."},{"gurmukhi":"ਬਿਬਾਯਦ ਕਿ ਈਂ ਕਾਰ ਰਾਹਤ ਰਸਾਂ। ੫੪।","roman":"Bibaayad ki een kaar raahat rasaan | 54 |","meaning_en":"this matter should bring comfort.","page":2543,"meaning_status":"draft","note":"ਰਾਹਤ ਰਸਾਂ: 'bringing relief'."}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":2543,"lines":[{"gurmukhi":"ਹਮੂੰ ਮਰਦ ਬਾਯਦ ਸ਼ਵਦ ਸੁਖ਼ਨਵਰ।","roman":"Hamoon marad baayad shavad sukhanvar |","meaning_en":"A man should be true to his word,","page":2543,"meaning_status":"draft","note":"ਸੁਖ਼ਨਵਰ: 'keeper of his word'."},{"gurmukhi":"ਨ ਸ਼ਿਕਮੇ ਦਿਗਰ ਦਰ ਦਹਾਨਿ ਦਿਗਰ। ੫੫।","roman":"Na shikme digar dar dahaani digar | 55 |","meaning_en":"not one thing in the belly and another in the mouth.","page":2543,"meaning_status":"draft","note":"Persian idiom: not saying one thing and meaning another."}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2543,"lines":[{"gurmukhi":"ਕਿ ਕਾਜ਼ੀ ਮਰਾ ਗੁਫ਼ਤਹ ਬੇਰੂੰ ਨਯਮ।","roman":"Ki kaazee maraa guftah beroon nayam |","meaning_en":"The Qazi told me (I should come), I will not refuse (?),","page":2543,"meaning_status":"draft","note":"Obscure: read as 'the Qazi has told me; I will not go back (on it)', or '... I will not come out'. Uncertain."},{"gurmukhi":"ਅਗਰ ਰਾਸਤੀ ਖ਼ੁਦ ਬਿਯਾਰੀ ਕਦਮ। ੫੬।","roman":"Agar raastee khud biyaaree kadam | 56 |","meaning_en":"if you yourself would step forward in truth.","page":2543,"meaning_status":"draft","note":"ਰਾਸਤੀ: truthfulness."}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2543,"lines":[{"gurmukhi":"ਤੁਰਾ ਗਰ ਬਬਾਯਦ ਬ ਕੌਲੇ ਕੁਰਾਂ।","roman":"Turaa gar babaayad ba kaule kuraan |","meaning_en":"If you want (me), on the word of the Quran,","page":2543,"meaning_status":"draft"},{"gurmukhi":"ਬਨਿਜ਼ਦੇ ਸ਼ੁਮਾ ਰਾ ਰਸਾਨਮ ਹੁਮਾ। ੫੭।","roman":"Banizde shumaa raa rasaanam humaa | 57 |","meaning_en":"I will send you that (written word) to your presence.","page":2543,"meaning_status":"draft","note":"ਹੁਮਾ: read as 'that (Quran) / it'; some read 'the Huma'. Uncertain."}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":2543,"lines":[{"gurmukhi":"ਕਿ ਤਸ਼ਰੀਫ ਦਰ ਕਸਬਹ ਕਾਂਗੜ ਕੁਨਦ।","roman":"Ki tashreeph dar kasbah kaangar kunad |","meaning_en":"That (you) be pleased to come to the town of Kangar,","page":2543,"meaning_status":"draft","note":"Kangar: a village in the Malwa region (Punjab)."},{"gurmukhi":"ਵਜ਼ਾਂ ਪਸ ਮੁਲਾਕਾਤ ਬਾਹਮ ਸ਼ਵਦ। ੫੮।","roman":"Vazaan pas mulaakaat baaham shavad | 58 |","meaning_en":"and after that we may meet one another.","page":2543,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":2545,"lines":[{"gurmukhi":"ਨ ਜ਼ਰੱਹ ਦਰੀਂ ਰਾਹ ਖ਼ਤਰਹ ਤੁਰਾਸਤ।","roman":"Na zarahh dareen raah khatrah turaasat |","meaning_en":"On this road there is not the least danger to you,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਹਮਹ ਕੌਮਿ ਬੈਰਾੜ ਹੁਕਮਿ ਮਰਾਸਤ। ੫੯।","roman":"Hamah kaumi bairaar hukmi maraasat | 59 |","meaning_en":"for the whole Brar clan is under my command.","page":2545,"meaning_status":"draft","note":"Brar: a Jat clan of the region, who were with the Guru."}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":2545,"lines":[{"gurmukhi":"ਬਿਯਾ ਤਾ ਬਮਨ ਖ਼ੁਦ ਜ਼ੁਬਾਨੀ ਕੁਨੇਮ।","roman":"Biyaa taa baman khud zubaanee kunem |","meaning_en":"Come to me, so that we may talk face to face,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਬਰੂਏ ਸ਼ੁਮਾ ਮੇਹਰਬਾਨੀ ਕੁਨੇਮ। ੬੦।","roman":"Barooe shumaa meharbaanee kunem | 60 |","meaning_en":"and I may show you kindness.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":2545,"lines":[{"gurmukhi":"ਯਕੇ ਅਸਪ ਸ਼ਾਇਸਤਏ ਯਕ ਹਜ਼ਾਰ।","roman":"Yake asap shaaistae yak hazaar |","meaning_en":"A horse worth a thousand (rupees),","page":2545,"meaning_status":"draft","note":"ਯਕੇ ਅਸਪ ਸ਼ਾਇਸਤਏ ਯਕ ਹਜ਼ਾਰ: 'a fine horse (worth) a thousand'."},{"gurmukhi":"ਬਿਯਾ ਤਾ ਬਗੀਰੀ ਬ ਮਨ ਈਂ ਦਿਯਾਰ। ੬੧।","roman":"Biyaa taa bageeree ba man een diyaar | 61 |","meaning_en":"come and take it from me in this land.","page":2545,"meaning_status":"draft","note":"Read as an invitation (or a gift offered); the exact sense is uncertain."}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2545,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਿ ਰਾ ਬੰਦਹੇ ਚਾਕਰੇਮ।","roman":"Shahinshaahi raa bandhe chaakrem |","meaning_en":"I am a servant of the King of kings;","page":2545,"meaning_status":"draft","note":"Read as: the Guru serves God, the true King of kings (not the emperor). Some read it as courtesy to the emperor; uncertain."},{"gurmukhi":"ਅਗਰ ਹੁਕਮ ਆਯਦ ਬ ਜਾਂ ਹਾਜ਼ਰੇਮ। ੬੨।","roman":"Agar hukam aayad ba jaan haazrem | 62 |","meaning_en":"if the order comes, I am present with my life.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2545,"lines":[{"gurmukhi":"ਅਗਰਚੇ ਬਿਆਯਦ ਬ ਫ਼ੁਰਮਾਨ ਮਨ।","roman":"Agarche biaayad ba furmaan man |","meaning_en":"If the command comes to me,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਹਜ਼ੂਰ ਤ ਬਿਯਾਯਮ ਹਮਹ ਜਾਨ ਤਨ। ੬੩।","roman":"Hazoor ta biyaayam hamah jaan tan | 63 |","meaning_en":"I will come to Your presence with all my life and body.","page":2545,"meaning_status":"draft","note":"ਹਜ਼ੂਰ: presence (of God, or of the addressee); uncertain."}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":2545,"lines":[{"gurmukhi":"ਅਗਰ ਤੋ ਬਯਜ਼ਦਾਂ ਪ੍ਰਸਤੀ ਕੁਨੀ।","roman":"Agar to bayazdaan prastee kunee |","meaning_en":"If you worship God,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਬ ਕਾਰੇ ਮਰਾ ਈਂ ਨ ਸੁਸਤੀ ਕੁਨੀ। ੬੪।","roman":"Ba kaare maraa een na sustee kunee | 64 |","meaning_en":"you will not be slow in this matter of mine.","page":2545,"meaning_status":"draft","note":"ਸੁਸਤੀ: slackness."}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2545,"lines":[{"gurmukhi":"ਬਿਬਾਯਦ ਕਿ ਯਜ਼ਦਾਂ ਸ਼ਨਾਸੀ ਕੁਨੀ।","roman":"Bibaayad ki yazdaan shanaasee kunee |","meaning_en":"You should recognise God,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਨ ਗੁਫ਼ਤਹ ਕਸੇ ਕਸ ਖ਼ਰਾਸ਼ੀ ਕੁਨੀ। ੬੫।","roman":"Na guftah kase kas kharaashee kunee | 65 |","meaning_en":"and not, on someone's word, harm others.","page":2545,"meaning_status":"draft","note":"ਖ਼ਰਾਸ਼ੀ: wounding, harming."}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2545,"lines":[{"gurmukhi":"ਤੁ ਮਸਨਦ ਨਸ਼ੀਂ ਸਰਵਰੇ ਕਾਇਨਾਤ।","roman":"Tu masnad nasheen saravre kaainaat |","meaning_en":"You sit on the throne, the chief of the universe,","page":2545,"meaning_status":"draft","note":"ਸਰਵਰੇ ਕਾਇਨਾਤ: 'lord of creation' (said with irony)."},{"gurmukhi":"ਕਿ ਅਜਬ ਅਸਤੁ ਇਨਸਾਫ਼ ਈਂ ਹਮ ਸਫ਼ਾਤ। ੬੬।","roman":"Ki ajab astu insaaf een ham safaat | 66 |","meaning_en":"but strange is this justice and these qualities of yours!","page":2545,"meaning_status":"draft","note":"ਸਫ਼ਾਤ: qualities."}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2545,"lines":[{"gurmukhi":"ਕਿ ਅਜਬ ਅਸਤੁ ਇਨਸਾਫ਼ੋ ਦੀਂ ਪਰਵਰੀ।","roman":"Ki ajab astu insaafo deen paravree |","meaning_en":"Strange is your justice and your upholding of the faith!","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਹੈਫ਼ ਅਸਤੁ ਸਦ ਹੈਫ਼ ਈਂ ਸਰਵਰੀ। ੬੭।","roman":"Ki haif astu sad haif een saravree | 67 |","meaning_en":"Alas, a hundred times alas, for such rule!","page":2545,"meaning_status":"draft","note":"ਹੈਫ਼: alas."}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2545,"lines":[{"gurmukhi":"ਕਿ ਅਜਬ ਅਸਤ ਅਜਬ ਅਸਤ ਤਕਵਾ ਸ਼ੁਮਾਂ।","roman":"Ki ajab asat ajab asat takvaa shumaan |","meaning_en":"Strange, strange is your piety!","page":2545,"meaning_status":"draft","note":"ਤਕਵਾ: piety, fear of God."},{"gurmukhi":"ਬਜੁਜ਼ ਰਾਸਤੀ ਸੁਖ਼ਨ ਗੁਫ਼ਤਨ ਜ਼ਯਾਂ। ੬੮।","roman":"Bajuz raastee sukhan guftan zayaan | 68 |","meaning_en":"To speak words other than the truth brings harm.","page":2545,"meaning_status":"draft","note":"ਜ਼ਯਾਂ: loss, harm."}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2545,"lines":[{"gurmukhi":"ਮਜ਼ਨ ਤੇਗ ਬਰ ਖੂੰਨ ਕਸ ਬੇਦਰੇਗ।","roman":"Mazan teg bar khoonn kas bedreg |","meaning_en":"Do not strike your sword mercilessly on anyone's blood;","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰਾ ਨੀਜ਼ ਖੂੰ ਅਸਤ ਬਾ ਚਰਖ਼ ਤੇਗ। ੬੯।","roman":"Turaa neez khoon asat baa charakh teg | 69 |","meaning_en":"your blood too will be (shed) by the sword of heaven.","page":2545,"meaning_status":"draft","note":"ਚਰਖ਼: the heavens (the turning sky)."}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2545,"lines":[{"gurmukhi":"ਤੁ ਗਾਫ਼ਲ ਮਸੌ ਮਰਦ ਯਜ਼ਦਾਂ ਸ਼ਨਾਸ।","roman":"Tu gaafal masau marad yazdaan shanaas |","meaning_en":"Do not be heedless, O man; recognise God,","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਓ ਬੇਨਿਆਜ਼ ਅਸਤੁ ਓ ਬੇ ਸੁਪਾਸ। ੭੦।","roman":"Ki o beniaaz astu o be supaas | 70 |","meaning_en":"for He needs nothing and wants no flattery.","page":2545,"meaning_status":"draft","note":"ਬੇਨਿਆਜ਼: free of need. ਬੇ ਸੁਪਾਸ: 'without (need of) thanks / flattery'; uncertain."}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2545,"lines":[{"gurmukhi":"ਕਿ ਊ ਬੇ ਮੁਹਾਬਸਤੁ ਸ਼ਾਹਾਨਿ ਸ਼ਾਹ।","roman":"Ki oo be muhaabastu shaahaani shaah |","meaning_en":"He is without fear, the King of kings,","page":2545,"meaning_status":"draft","note":"ਬੇ ਮੁਹਾਬ: 'fearing none'."},{"gurmukhi":"ਜ਼ਿਮੀਨੋ ਜ਼ਮਾਂ ਸੱਚਏ ਪਾਤਿਸ਼ਾਹ। ੭੧।","roman":"Zimeeno zamaan sacchae paatishaah | 71 |","meaning_en":"the true Emperor of earth and time.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2545,"lines":[{"gurmukhi":"ਖ਼ੁਦਾਵੰਦਿ ਈਜ਼ਦ ਜ਼ਮੀਨੋ ਜ਼ਮਾਂ।","roman":"Khudaavandi eezad zameeno zamaan |","meaning_en":"God is the Lord of earth and time;","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਕੁਨਿੰਦਹਸਤ ਹਰ ਕਸ ਮਕੀਨੋ ਮਕਾਂ। ੭੨।","roman":"Kunindahsat har kas makeeno makaan | 72 |","meaning_en":"He is the maker of every dweller and every dwelling.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2545,"lines":[{"gurmukhi":"ਹਮ ਅਜ਼ ਪੀਰ ਮੋਰਹ ਹਮ ਅਜ਼ ਫ਼ੀਲ ਤਨ।","roman":"Ham az peer morah ham az feel tan |","meaning_en":"From the old ant to the elephant-bodied,","page":2545,"meaning_status":"draft","note":"ਪੀਰ ਮੋਰਹ: 'the old ant' (the smallest creature)."},{"gurmukhi":"ਕਿ ਆਜਜ਼ ਨਿਵਾਜ਼ ਅਸਤੋ ਗਾਫ਼ਲ ਸ਼ਿਕੰਨ। ੭੩।","roman":"Ki aajaz nivaaz asto gaafal shikann | 73 |","meaning_en":"He cherishes the humble and breaks the heedless.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":2545,"lines":[{"gurmukhi":"ਕਿ ਊ ਰਾ ਚੁ ਇਸਮ ਅਸਤੁ ਆਜਜ਼ ਨਿਵਾਜ਼।","roman":"Ki oo raa chu isam astu aajaz nivaaz |","meaning_en":"Since His name is 'Cherisher of the Humble',","page":2545,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਊ ਬੇ ਸੁਪਾਸ ਅਸਤ ਊ ਬੇ ਨਿਯਾਜ਼। ੭੪।","roman":"Ki oo be supaas asat oo be niyaaz | 74 |","meaning_en":"He needs no flattery and no gifts.","page":2545,"meaning_status":"draft"}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2547,"lines":[{"gurmukhi":"ਕਿ ਊ ਬੇ ਨਗੂੰ ਅਸਤੁ ਊ ਬੇ ਚਗੂੰ।","roman":"Ki oo be nagoon astu oo be chagoon |","meaning_en":"He is without (worldly) form and without equal;","page":2547,"meaning_status":"draft","note":"ਬੇ ਨਗੂੰ ... ਬੇ ਚਗੂੰ: 'beyond how and beyond such-like'; uncertain."},{"gurmukhi":"ਕਿ ਊ ਰਹਿਨੁਮਾ ਅਸਤੁ ਊ ਰਹਿਨਮੂੰ। ੭੫।","roman":"Ki oo rahinumaa astu oo rahinmoon | 75 |","meaning_en":"He is the guide and He shows the way.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2547,"lines":[{"gurmukhi":"ਕਿ ਬਰ ਸਰ ਤੁਰਾ ਫ਼ਰਜ਼ ਕਸਮਿ ਕੁਰਾਂ।","roman":"Ki bar sar turaa faraz kasmi kuraan |","meaning_en":"The oath on the Quran is a duty on your head:","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਬ ਗੁਫ਼ਤਹ ਸ਼ੁਮਾ ਕਾਰ ਖ਼ੂਬੀ ਰਸਾਂ। ੭੬।","roman":"Ba guftah shumaa kaar khoobee rasaan | 76 |","meaning_en":"carry the matter to a good end, as you said.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":2547,"lines":[{"gurmukhi":"ਬਿਬਾਯਦ ਤੁ ਦਾਨਸ਼ ਪ੍ਰਸਤੀ ਕੁਨੀ।","roman":"Bibaayad tu daanash prastee kunee |","meaning_en":"You should act with wisdom,","page":2547,"meaning_status":"draft","note":"ਦਾਨਸ਼ ਪ੍ਰਸਤੀ: 'devotion to wisdom'."},{"gurmukhi":"ਬਕਾਰੇ ਸ਼ੁਮਾ ਚੇਰਹ ਦਸਤੀ ਕੁਨੀ। ੭੭।","roman":"Bakaare shumaa cherah dastee kunee | 77 |","meaning_en":"and be skilful in your affairs.","page":2547,"meaning_status":"draft","note":"ਚੇਰਹ ਦਸਤੀ: 'skilfulness'; uncertain."}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2547,"lines":[{"gurmukhi":"ਚਿਹਾ ਸ਼ੁਦ ਕਿ ਚੂੰ ਬੱਚਗਾਂ ਕੁਸ਼ਤਹ ਚਾਰ।","roman":"Chihaa shud ki choon bacchgaan kushtah chaar |","meaning_en":"What of it that you killed my four children,","page":2547,"meaning_status":"draft","note":"The Guru's four sons were martyred: two in battle at Chamkaur, two bricked alive at Sirhind."},{"gurmukhi":"ਕਿ ਬਾਕੀ ਬਮਾਂਦਸਤੁ ਪੇਚੀਦਹ ਮਾਰ। ੭੮।","roman":"Ki baakee bamaandastu pecheedah maar | 78 |","meaning_en":"when the coiled snake (the Khalsa) still remains?","page":2547,"meaning_status":"draft","note":"ਪੇਚੀਦਹ ਮਾਰ: 'the coiled serpent', read as the Khalsa, or as the Guru himself."}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2547,"lines":[{"gurmukhi":"ਚਿ ਮਰਦੀ ਕਿ ਅਖ਼ਗਰ ਖ਼ਮੋਸ਼ਾਂ ਕੁਨੀ।","roman":"Chi mardee ki akhgar khamoshaan kunee |","meaning_en":"What bravery is it to put out a few sparks,","page":2547,"meaning_status":"draft","note":"ਅਖ਼ਗਰ: sparks, embers."},{"gurmukhi":"ਕਿ ਆਤਿਸ਼ ਦਮਾਂ ਰਾ ਫ਼ਰੋਜ਼ਾਂ ਕੁਨੀ। ੭੯।","roman":"Ki aatish damaan raa farozaan kunee | 79 |","meaning_en":"when you only fan the fire into flame?","page":2547,"meaning_status":"draft","note":"ਆਤਿਸ਼ ਦਮਾਂ: 'the blazing fire'."}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2547,"lines":[{"gurmukhi":"ਚਿ ਖ਼ੁਸ਼ ਗੁਫ਼ਤ ਫ਼ਿਰਦੌਸੀਏ ਖ਼ੁਸ਼ ਜ਼ੁਬਾਂ।","roman":"Chi khush gufat firdausee'e khush zubaan |","meaning_en":"How well the sweet-tongued Firdausi said:","page":2547,"meaning_status":"draft","note":"Firdausi: the Persian poet of the Shahnama."},{"gurmukhi":"ਸ਼ਿਤਾਬੀ ਬਵਦ ਕਾਰਿ ਆਹਰਮਨਾ। ੮੦।","roman":"Shitaabee bavad kaari aahramnaa | 80 |","meaning_en":"'Haste is the work of the devil.'","page":2547,"meaning_status":"draft","note":"ਆਹਰਮਨ: Ahriman, the devil."}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2547,"lines":[{"gurmukhi":"ਕਿ ਮਾ ਬਾਰਗਹਿ ਹਜ਼ਰਤ ਆਯਦ ਸ਼ੁਮਾਂ।","roman":"Ki maa baaraghi hazrat aayad shumaan |","meaning_en":"When you come to the court of the Lord,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਅਜ਼ਾਂ ਰੋਜ਼ ਬਾਸ਼ੇਦ ਸ਼ਾਹਿਦ ਸ਼ੁਮਾਂ। ੮੧।","roman":"Azaan roz baashed shaahid shumaan | 81 |","meaning_en":"on that day you will be a witness (against yourself).","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":2547,"lines":[{"gurmukhi":"ਵਗਰਨਹ ਤੁ ਈਂ ਰਾ ਫ਼ਰਾਮੋਸ਼ ਕੁਨਦ।","roman":"Vagarnah tu een raa faraamosh kunad |","meaning_en":"Otherwise, if you forget this,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰਾ ਹਮ ਫ਼ਰਾਮੋਸ਼ ਯਜ਼ਦਾਂ ਕੁਨਦ। ੮੨।","roman":"Turaa ham faraamosh yazdaan kunad | 82 |","meaning_en":"God too will forget you.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2547,"lines":[{"gurmukhi":"ਅਗਰ ਕਾਰਿ ਈਂ ਬਰ ਤੂ ਬਸਤੀ ਕਮਰ।","roman":"Agar kaari een bar too bastee kamar |","meaning_en":"If you gird your loins for this work,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਬਾਸ਼ਦ ਤੁਰਾ ਬਹਰਹ ਵਰ। ੮੩।","roman":"Khudaavand baashad turaa bahrah var | 83 |","meaning_en":"the Lord will give you a (good) share.","page":2547,"meaning_status":"draft","note":"ਬਹਰਹ ਵਰ: 'a share / fruitful'."}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2547,"lines":[{"gurmukhi":"ਕਿ ਈਂ ਕਾਰ ਨੇਕਅਸਤੁ ਦੀਂ ਪਰਵਰੀ।","roman":"Ki een kaar neka'astu deen paravree |","meaning_en":"This is a good deed and an upholding of the faith,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਯਜ਼ਦਾਂ ਸ਼ਨਾਸੀ ਬਜਾਂ ਬਰਤਰੀ। ੮੪।","roman":"Chu yazdaan shanaasee bajaan baratree | 84 |","meaning_en":"for knowing God is above (even) life.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2547,"lines":[{"gurmukhi":"ਤੁਰਾ ਮਨ ਨ ਦਾਨਮ ਕਿ ਯਜ਼ਦਾਂ ਸ਼ਨਾਸ।","roman":"Turaa man na daanam ki yazdaan shanaas |","meaning_en":"I do not think you know God,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਬਰਾਮਦ ਜ਼ਿ ਤੂ ਕਾਰਹਾ ਦਿਲ ਖ਼ਰਾਸ। ੮੫।","roman":"Baraamad zi too kaarhaa dil kharaas | 85 |","meaning_en":"for deeds that wound the heart have come from you.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2547,"lines":[{"gurmukhi":"ਸ਼ਨਾਸਦ ਹਮੀਂ ਤੂ ਨ ਯਜ਼ਦਾਂ ਕਰੀਮ।","roman":"Shanaasad hameen too na yazdaan kareem |","meaning_en":"The bountiful God does not recognise you,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਨ ਖ਼੍ਵਾਹਦ ਹਮੀ ਤੂ ਬਦੌਲਤ ਅਜ਼ੀਮ। ੮੬।","roman":"Na khvaahad hamee too badaulat azeem | 86 |","meaning_en":"nor does He want you, for all your great wealth.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2547,"lines":[{"gurmukhi":"ਅਗਰ ਸਦ ਕੁਰਾਂ ਰਾ ਬਖ਼ੁਰਦੀ ਕਸਮ।","roman":"Agar sad kuraan raa bakhurdee kasam |","meaning_en":"Even if you swore a hundred times on the Quran,","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਮਰਾ ਏਤਬਾਰੇ ਨ ਈਂ ਜ਼ਰਹ ਦਮ। ੮੭।","roman":"Maraa etbaare na een zarah dam | 87 |","meaning_en":"I would not trust you for a moment.","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2547,"lines":[{"gurmukhi":"ਹਜ਼ੂਰੀ ਨ ਆਯਮ ਨ ਈਂ ਰਹ ਸ਼ਵਮ।","roman":"Hazooree na aayam na een rah shavam |","meaning_en":"I will not come to your presence, nor take this road;","page":2547,"meaning_status":"draft"},{"gurmukhi":"ਅਗਰ ਸ਼ਹ ਬਖ਼੍ਵਾਹਦ ਮਨ ਆਂ ਜਾ ਰਵਮ। ੮੮।","roman":"Agar shah bakhvaahad man aan jaa ravam | 88 |","meaning_en":"if the King (God) wishes, I will go there.","page":2547,"meaning_status":"draft","note":"ਸ਼ਹ: 'the King', read as God (or the emperor); uncertain."}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2547,"lines":[{"gurmukhi":"ਖ਼ੁਸ਼ਸ਼ ਸ਼ਾਹਿ ਸ਼ਾਹਾਨ ਔਰੰਗਜ਼ੇਬ।","roman":"Khushash shaahi shaahaan aurangzeb |","meaning_en":"Fortunate is the King of kings, Aurangzeb,","page":2547,"meaning_status":"draft","note":"Here the Guru acknowledges the emperor's worldly qualities before turning to his faults; many read these lines as ironic."},{"gurmukhi":"ਕਿ ਚਾਲਾਕ ਦਸਤੁ ਅਸਤੁ ਚਾਬੁਕ ਰਕੇਬ। ੮੯।","roman":"Ki chaalaak dastu astu chaabuk rakeb | 89 |","meaning_en":"skilful of hand and a swift rider.","page":2547,"meaning_status":"draft","note":"ਚਾਬੁਕ ਰਕੇਬ: 'quick in the stirrup'."}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2547,"lines":[{"gurmukhi":"ਚਿ ਹੁਸਨਲ ਜਮਾਲਸਤੁ ਰੌਸ਼ਨ ਜ਼ਮੀਰ।","roman":"Chi husnal jamaalastu raushan zameer |","meaning_en":"Handsome, of bright mind,","page":2547,"meaning_status":"draft","note":"ਰੌਸ਼ਨ ਜ਼ਮੀਰ: 'enlightened conscience / bright mind'."},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਮੁਲਕ ਅਸਤੁ ਸਾਹਿਬ ਅਮੀਰ। ੯੦।","roman":"Khudaavand mulak astu saahib ameer | 90 |","meaning_en":"lord of the kingdom, master and commander;","page":2547,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":2549,"lines":[{"gurmukhi":"ਕਿ ਤਰਤੀਬ ਦਾਨਸ਼ ਬ ਤਦਬੀਰ ਤੇਗ।","roman":"Ki tarteeb daanash ba tadbeer teg |","meaning_en":"orderly in wisdom, skilled with the sword,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦਿ ਦੇਗੋ ਖ਼ੁਦਾਵੰਦਿ ਤੇਗ। ੯੧।","roman":"Khudaavandi dego khudaavandi teg | 91 |","meaning_en":"lord of the cauldron (charity) and lord of the sword.","page":2549,"meaning_status":"draft","note":"ਦੇਗੋ ਤੇਗ: 'the cauldron and the sword', charity and might."}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2549,"lines":[{"gurmukhi":"ਕਿ ਰੌਸ਼ਨ ਜ਼ਮੀਰ ਅਸਤੁ ਹੁਸਨੁਲ ਜਮਾਲ।","roman":"Ki raushan zameer astu husnul jamaal |","meaning_en":"Of bright mind and handsome,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਬਖ਼ਸ਼ਿੰਦਹੇ ਮੁਲਕੋ ਮਾਲ। ੯੨।","roman":"Khudaavand bakhshindhe mulko maal | 92 |","meaning_en":"the lord who gives away land and wealth;","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2549,"lines":[{"gurmukhi":"ਕਿ ਬਖ਼ਸ਼ਿਸ਼ ਕਬੀਰ ਅਸਤੁ ਦਰ ਜੰਗ ਕੋਹ।","roman":"Ki bakhshish kabeer astu dar jang koh |","meaning_en":"great in giving, a mountain in war,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਮਲਾਯਕ ਸਿਫ਼ਤ ਚੂੰ ਸੁਰੱਯਾ ਸ਼ਿਕੋਹ। ੯੩।","roman":"Malaayak sifat choon suryyaa shikoh | 93 |","meaning_en":"of angelic qualities, majestic as the Pleiades.","page":2549,"meaning_status":"draft","note":"ਸੁਰੱਯਾ: the Pleiades."}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":2549,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਿ ਔਰੰਗਜ਼ੇਬ ਆਲਮੀਂ।","roman":"Shahinshaahi aurangzeb aalmeen |","meaning_en":"Emperor Aurangzeb, (ruler) of the world,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਦਾਰਾਇ ਦੌਰ ਅਸਤੁ ਦੂਰ ਅਸਤ ਦੀਂ। ੯੪।","roman":"Ki daaraai daur astu door asat deen | 94 |","meaning_en":"you are the master of the age, but far from faith.","page":2549,"meaning_status":"draft","note":"ਦਾਰਾਇ ਦੌਰ: 'ruler of the age'. ਦੂਰ ਅਸਤ ਦੀਂ: 'far from religion'."}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2549,"lines":[{"gurmukhi":"ਮਨਮ ਕੁਸ਼ਤਹਅਮ ਕੋਹੀਆ ਬੁਤਪ੍ਰਸਤ।","roman":"Manam kushatha'am koheeaa butprasat |","meaning_en":"I have killed the idol-worshipping hill (rajas);","page":2549,"meaning_status":"draft","note":"Refers to the hill chiefs who fought the Guru."},{"gurmukhi":"ਕਿ ਆਂ ਬੁਤ ਪ੍ਰਸਤੰਦੋ ਮਨ ਬੁਤ ਸ਼ਿਕਸਤ। ੯੫।","roman":"Ki aan but prastando man but shiksat | 95 |","meaning_en":"for they worship idols, and I am a breaker of idols.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":2549,"lines":[{"gurmukhi":"ਬਬੀਂ ਗਰਦਸ਼ੇ ਬੇਵਫ਼ਾਏ ਜ਼ਮਾ।","roman":"Babeen garadshe bevfaae zamaa |","meaning_en":"See the turning of the faithless time:","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਪਸੇ ਪੁਸ਼ਤ ਉਫ਼ਤਦ ਰਸਾਨਦ ਜ਼ਿਯਾਂ। ੯੬।","roman":"Pase pushat uftad rasaanad ziyaan | 96 |","meaning_en":"it comes up from behind and does harm.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2549,"lines":[{"gurmukhi":"ਬਬੀਂ ਕੁਦਰਤੇ ਨੇਕ ਯਜ਼ਦਾਨਿ ਪਾਕ।","roman":"Babeen kudarte nek yazdaani paak |","meaning_en":"See the good power of the pure God:","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਅਜ਼ ਯਕ ਬ ਦਹ ਲਖ਼ ਰਸਾਨਦ ਹਲਾਕ। ੯੭।","roman":"Ki az yak ba dah lakh rasaanad halaak | 97 |","meaning_en":"through one, He brings destruction on ten lakh.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2549,"lines":[{"gurmukhi":"ਕਿ ਦੁਸ਼ਮਨ ਕੁਨਦ ਮਿਹਰਬਾਂ ਅਸਤੁ ਦੋਸਤ।","roman":"Ki dushman kunad miharbaan astu dosat |","meaning_en":"What can an enemy do when the Friend is kind?","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਬਖ਼ਸ਼ਿੰਦਗੀ ਕਾਰ ਬਖ਼ਸ਼ਿੰਦਹ ਓਸਤ। ੯੮।","roman":"Ki bakhshindgee kaar bakhshindah osat | 98 |","meaning_en":"For giving is the work of the Giver.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2549,"lines":[{"gurmukhi":"ਰਿਹਾਈ ਦਿਹੋ ਰਹਿਨੁਮਾਈ ਦਿਹਦ।","roman":"Rihaaee diho rahinumaaee dihad |","meaning_en":"He gives deliverance and gives guidance,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ੁਬਾਂ ਰਾ ਬਸਿਫ਼ਤ ਆਸ਼ਨਾਈ ਦਿਹਦ। ੯੯।","roman":"Zubaan raa basifat aashnaaee dihad | 99 |","meaning_en":"and gives the tongue the gift of praise.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2549,"lines":[{"gurmukhi":"ਖ਼ਸਮ ਰਾ ਚੁ ਕੋਰਊ ਕੁਨਦ ਵਕਤਿ ਕਾਰ।","roman":"Khasam raa chu koraoo kunad vakti kaar |","meaning_en":"At the time of action He blinds the enemy,","page":2549,"meaning_status":"draft","note":"ਕੋਰ: blind."},{"gurmukhi":"ਯਤੀਮਾਂ ਬਿਰੂੰ ਮੇ ਬੁਰਦ ਬੇਅਜ਼ਾਰ। ੧੦੦।","roman":"Yateemaan biroon me burad beazaar | 100 |","meaning_en":"and brings out the orphans unharmed.","page":2549,"meaning_status":"draft","note":"ਯਤੀਮ: orphans, the helpless."}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2549,"lines":[{"gurmukhi":"ਹਰਾਂ ਕਸ ਕਿ ਓ ਰਾਸਤ ਬਾਜ਼ੀ ਕੁਨਦ।","roman":"Haraan kas ki o raasat baazee kunad |","meaning_en":"Whoever acts honestly,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਰਹੀਮੇ ਬਰੋ ਰਹਮ ਸਾਜ਼ੀ ਕੁਨਦ। ੧੦੧।","roman":"Raheeme baro raham saazee kunad | 101 |","meaning_en":"the Merciful One shows mercy to him.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2549,"lines":[{"gurmukhi":"ਕਸੇ ਖ਼ਿਦਮਤ ਆਯਦ ਬਸੇ ਦਿਲੋ ਜਾਂ।","roman":"Kase khidmat aayad base dilo jaan |","meaning_en":"Whoever serves Him with heart and soul,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਬਖ਼ਸ਼ੀਦ ਬਰ ਵੈ ਅਮਾਂ। ੧੦੨।","roman":"Khudaavand bakhsheed bar vai amaan | 102 |","meaning_en":"the Lord grants him protection.","page":2549,"meaning_status":"draft","note":"ਅਮਾਂ: safety."}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2549,"lines":[{"gurmukhi":"ਚਿ ਦੁਸ਼ਮਨ ਬਰਾਂ ਹੀਲਹ ਸਾਜ਼ੀ ਕੁਨਦ।","roman":"Chi dushman baraan heelah saazee kunad |","meaning_en":"What can an enemy do by trickery against him,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਅਗਰ ਰਹਨੁਮਾ ਬਰ ਵੈ ਰਾਜ਼ੀ ਸ਼ਵਦ । ੧੦੩।","roman":"Agar rahnumaa bar vai raazee shavad | 103 |","meaning_en":"if the Guide is pleased with him?","page":2549,"flags":[{"code":"space","reason":"word space printed as a gap (6.0pt), space inserted"}],"meaning_status":"draft"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2549,"lines":[{"gurmukhi":"ਅਗਰ ਯਕ ਬਰ ਆਯਦ ਦਹੋ ਦਹ ਹਜ਼ਾਰ।","roman":"Agar yak bar aayad daho dah hazaar |","meaning_en":"If ten times ten thousand come against one,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਨਿਗਹਬਾਨ ਊ ਰਾ ਸ਼ਵਦ ਕਿਰਦਗਾਰ। ੧੦੪।","roman":"Nigahbaan oo raa shavad kiradgaar | 104 |","meaning_en":"the Creator becomes his protector.","page":2549,"meaning_status":"draft","note":"ਕਿਰਦਗਾਰ: Creator."}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2549,"lines":[{"gurmukhi":"ਤੁਰਾ ਗਰ ਨਜ਼ਰ ਹਸਤ ਲਸ਼ਕਰ ਵ ਜ਼ਰ।","roman":"Turaa gar nazar hasat lashkar va zar |","meaning_en":"If your eye is on your army and gold,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮਾਰਾ ਨਿਗਹ ਅਸਤੁ ਯਜ਼ਦਾਂ ਸ਼ੁਕਰ। ੧੦੫।","roman":"Ki maaraa nigah astu yazdaan shukar | 105 |","meaning_en":"my eye is on God, in thanks.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2549,"lines":[{"gurmukhi":"ਕਿ ਊ ਰਾ ਗਰੂਰ ਅਸਤ ਬਰ ਮੁਲਕੁ ਮਾਲ।","roman":"Ki oo raa garoor asat bar mulku maal |","meaning_en":"He (you) is proud of kingdom and wealth,","page":2549,"meaning_status":"draft"},{"gurmukhi":"ਵ ਮਾਰਾ ਪਨਾਹ ਅਸਤੁ ਯਜ਼ਦਾਂ ਅਕਾਲ। ੧੦੬।","roman":"Va maaraa panaah astu yazdaan akaal | 106 |","meaning_en":"and my refuge is God, the Timeless.","page":2549,"meaning_status":"draft"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2551,"lines":[{"gurmukhi":"ਤੁ ਗਾਫ਼ਲ ਮਸ਼ੌ ਜ਼ੀ ਸਿਪੰਜੀ ਸਰਾਇ।","roman":"Tu gaafal mashau zee sipanjee saraai |","meaning_en":"Do not be heedless of this inn of three days,","page":2551,"meaning_status":"draft","note":"ਸਿਪੰਜੀ ਸਰਾਇ: 'the three-day inn', this short life."},{"gurmukhi":"ਕਿ ਆਲਮ ਬਗੁਜ਼ਰਦ ਸਰੇ ਜਾ ਬਜਾਇ। ੧੦੭।","roman":"Ki aalam baguzrad sare jaa bajaai | 107 |","meaning_en":"for the world passes away from place to place.","page":2551,"meaning_status":"draft"}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2551,"lines":[{"gurmukhi":"ਬਬੀਂ ਗਰਦਸ਼ਿ ਬੇਵਫ਼ਾਏ ਜ਼ਮਾਂ।","roman":"Babeen garadshi bevfaae zamaan |","meaning_en":"See the turning of the faithless time,","page":2551,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਬਰ ਹਰ ਬੁਗੁਜ਼ਰਦ ਮਕੀਨੋ ਮਕਾਂ। ੧੦੮।","roman":"Ki bar har buguzrad makeeno makaan | 108 |","meaning_en":"which passes over every dweller and every dwelling.","page":2551,"meaning_status":"draft"}]},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2551,"lines":[{"gurmukhi":"ਤੁ ਗਰ ਜ਼ਬਰ ਆਜਜ਼ ਖ਼ਰਾਸ਼ੀ ਮਕੁਨ।","roman":"Tu gar zabar aajaz kharaashee makun |","meaning_en":"Though you are strong, do not torment the weak;","page":2551,"meaning_status":"draft"},{"gurmukhi":"ਕਸਮ ਰਾ ਬ ਤੇਸ਼ਹ ਤਰਾਸ਼ੀ ਮਕੁਨ। ੧੦੯।","roman":"Kasam raa ba teshah taraashee makun | 109 |","meaning_en":"do not cut (break) your oath with an axe.","page":2551,"meaning_status":"draft","note":"ਤੇਸ਼ਹ: an axe or adze."}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2551,"lines":[{"gurmukhi":"ਚੁ ਹਕ ਯਾਰ ਬਾਸ਼ਦ ਚਿ ਦੁਸ਼ਮਨ ਕੁਨਦ।","roman":"Chu hak yaar baashad chi dushman kunad |","meaning_en":"When God is the friend, what can the enemy do,","page":2551,"meaning_status":"draft","note":"ਹਕ: God (the Truth)."},{"gurmukhi":"ਅਗਰ ਦੁਸ਼ਮਨੀ ਰਾ ਬ ਸਦ ਤਨ ਕੁਨਦ। ੧੧੦।","roman":"Agar dushamnee raa ba sad tan kunad | 110 |","meaning_en":"even if he makes his enmity in a hundred bodies (ways)?","page":2551,"meaning_status":"draft"}]},{"type":"verse","number":[111,1],"number_text":"੧੧੧। ੧।","page":2551,"lines":[{"gurmukhi":"ਖ਼ਸਮ ਦੁਸ਼ਮਨੀ ਗਰ ਹਜ਼ਾਰ ਆਵੁਰਦ।","roman":"Khasam dushamnee gar hazaar aavurad |","meaning_en":"If the enemy brings a thousand enmities,","page":2551,"meaning_status":"draft"},{"gurmukhi":"ਨ ਯਕ ਮੂਇ ਊ ਰਾ ਅਜ਼ਾਰ ਆਵੁਰਦ। ੧੧੧। ੧।","roman":"Na yak mooi oo raa azaar aavurad | 111 | 1 |","meaning_en":"he cannot harm even a single hair of him (the one God protects).","page":2551,"meaning_status":"draft"}]}],"ending":null});
